        var result = v === '' ? 'empty' : (!graded ? 'neutral' : (k.split('|').map(norm).indexOf(norm(v)) >= 0 ? 'correct' : 'wrong'));
        var shown = graded || SEND_OPEN_TEXT ? v.slice(0, 255) : (v === '' ? '' : 'answered');
        push(id, shown, result, graded, 'fill-in', shown);
